import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
customer_demand_records = [r for r in records if r['source'].endswith('customer_demand.csv')]
customers = [r['values']['customer'] for r in customer_demand_records]
demand = {r['values']['customer']: float(r['values']['demand']) for r in customer_demand_records}
supply_capacity_records = [r for r in records if r['source'].endswith('supply_capacity.csv')]
suppliers = [r['values']['Unnamed: 0'] for r in supply_capacity_records]
supply_capacity = {r['values']['Unnamed: 0']: float(r['values']['supply_capacity']) for r in supply_capacity_records}
cost_records = [r for r in records if r['source'].endswith('transportation_costs.csv')]
cost = {}
for r in cost_records:
    i = r['values']['Unnamed: 0']
    cost[i] = {}
    for j in customers:
        if j not in r['values']:
            raise ValueError(f'Missing cost for supplier {i}, customer {j}')
        cost[i][j] = float(r['values'][j])
for i in suppliers:
    if i not in cost:
        raise ValueError(f'Missing cost row for supplier {i}')
    for j in customers:
        if j not in cost[i]:
            raise ValueError(f'Missing cost for supplier {i}, customer {j}')
for j in customers:
    if j not in demand:
        raise ValueError(f'Missing demand for customer {j}')
for i in suppliers:
    if i not in supply_capacity:
        raise ValueError(f'Missing supply capacity for supplier {i}')
m = gp.Model('BrewCo_Transportation')
x_vars = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((cost[i][j] * x_vars[i, j] for i in suppliers for j in customers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for i in suppliers)) >= demand[j] for j in customers), name='')
m.addConstrs((gp.quicksum((x_vars[i, j] for j in customers)) <= supply_capacity[i] for i in suppliers), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')